43 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0627\u0631\u0641\u0639\u064a \u0623\u062d\u062f \u0627\u0644\u062f\u0645\u0628\u0644 \u0623\u0645\u0627\u0645\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0642\u0645 \u0628\u0627\u0644\u062a\u0628\u062f\u064a\u0644 \u0628\u064a\u0646 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0387","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0387-gH5fRsC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0387-gH5fRsC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d064692c-ab0f-5184-8ab8-aba3ed20b6b0","source_id":"1676","name_en":"dumbbell seated alternate hammer curl on exercise ball","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u064a\u062c\u0644\u0633 \u0645\u0637\u0631\u0642\u0629 \u0628\u062f\u064a\u0644\u0629 \u062d\u0644\u064a\u0642\u0629 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell seated alternate hammer curl on exercise ball"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell seated alternate hammer curl on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and your back straight.\nHold a dumbbell in each hand with your palms facing your body and your arms fully extended.\nKeeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.\nContinue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly lower the dumbbell back to the starting position.\nRepeat the movement with the opposite arm.\nContinue alternating arms for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u0648\u0627\u062c\u0647\u0629 \u0644\u062c\u0633\u0645\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u062b\u0645 \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0623\u062d\u062f \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0646\u0634\u0642 \u0648\u0623\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0645\u0639\u0627\u0643\u0633\u0629.\n\u0627\u0633\u062a\u0645\