0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0623\u062d\u062f \u0627\u0644\u062f\u0645\u0628\u0644\u064a\u0646 \u0644\u0623\u0639\u0644\u0649 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0622\u062e\u0631 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0622\u062e\u0631 \u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3546","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3546-q7qkONO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3546-q7qkONO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":