l seated one arm bicep curl on exercise ball with leg raised"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and your back straight.\nHold a dumbbell in one hand with your palm facing up and your arm fully extended.\nPlace your other hand on your hip for stability.\nSlowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.\nPause for a moment at the top of the movement, squeezing your bicep.\nSlowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions.\nSwitch arms and repeat the exercise.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0630\u0631\u0627\u0639\u0643 \u0645\u0645\u062a\u062f\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u0623\u062e\u0631\u0649 \u0639\u0644\u0649 \u0648\u0631\u0643\u0643 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1679","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1679-84sESNy.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1679-84sESNy.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"04cd1e74-acef-5dac-88b5-970e8ede34eb","source_id":"0398","name_en":"dumbbell seated one arm kickback","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u064a\u062c\u0644\u0633 \u0631\u0634\u0648\u0629 \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629","match_names":["dumbbel