f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629 \u062b\u0645 \u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0642\u062f\u0645\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062a\u0643\u0648\u0646 \u0642\u062f\u0645\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0645\u0631\u062a\u0641\u0639\u0629 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u062f\u0631\u062c\u0629.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0648\u0648\u0631\u0643\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0645\u062b\u0646\u064a\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0643\u0639\u0628\u0643 \u0627\u0644\u062e\u0644\u0641\u064a \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0410","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0410-qx4fgX7.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0410-qx4fgX7.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"84e3857d-ae25-54f0-824e-bd70df7bf6c2","source_id":"0411","name_en":"dumbbell single leg squat","name_ar":"\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629","match_names":["dumbbell single leg squat"],"muscle":"glutes","equipment":"dumbbell","aliases":["dumbbell single leg squat"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\nExtend one leg forward and keep it off the ground throughout the exercise.\nBend your standing leg and lower your body down as if sitting back into a chair.\nKeep your chest up and your back straight.\nPause for a moment at the bottom, then push through your heel to return to the starting position.\nRepeat for the desired number of repetitions, then switch legs.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0642\u0645 \u0628\u0645\u062f \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0628\u0639\u064a\u062f\u0629 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u062b\u0646\u0650 \u0633\u0627\u0642\u0643 \u0627\u0644\u0648\u0627\u0642\u0641\u0629 \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0633\u064a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0411","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0411-H6ybluc.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0411-H6ybluc.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
